                    JsonSerializer.Serialize(writer, matchUpdate.TicketRevenueGbp, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("ticket_revenue_gbp");
            if (matchUpdate.TurningPointsOption.IsSet)
                if (matchUpdate.TurningPointsOption.Value != null)
                {
                    writer.WritePropertyName("turning_points");
                    JsonSerializer.Serialize(writer, matchUpdate.TurningPoints, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("turning_points");
            if (matchUpdate.WeatherTempCelsiusOption.IsSet)
                if (matchUpdate.WeatherTempCelsiusOption.Value != null)
                    writer.WriteNumber("weather_temp_celsius", matchUpdate.WeatherTempCelsiusOption.Value!.Value);
                else
                    writer.WriteNull("weather_temp_celsius");
        }
    }
}
